import{_ as a,o as i,c as o,a2 as l}from"./chunks/framework.CgxQ0r6v.js";const g=JSON.parse('{"title":"Unidad Curricular: Proyecto Socio Tecnológico IV","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_IV/Contenido_Programatico.md","filePath":"materias/Proyecto_Sociotecnologico_IV/Contenido_Programatico.md"}'),t={name:"materias/Proyecto_Sociotecnologico_IV/Contenido_Programatico.md"};function r(n,e,c,s,d,u){return i(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="unidad-curricular-proyecto-socio-tecnologico-iv" tabindex="-1">Unidad Curricular: Proyecto Socio Tecnológico IV <a class="header-anchor" href="#unidad-curricular-proyecto-socio-tecnologico-iv" aria-label="Permalink to &quot;Unidad Curricular: Proyecto Socio Tecnológico IV&quot;">​</a></h1><p><strong>Trayecto:</strong> IV <strong>Duración:</strong> 3 trimestres <strong>Tipo:</strong> Proyecto</p><table tabindex="0"><thead><tr><th style="text-align:left;">Densidad Semanal</th><th style="text-align:left;">Hora Acad.</th><th style="text-align:left;">HTEA</th><th style="text-align:left;">HTEI</th><th style="text-align:left;">THTE</th></tr></thead><tbody><tr><td style="text-align:left;">60&#39;</td><td style="text-align:left;">-</td><td style="text-align:left;">-</td><td style="text-align:left;">-</td><td style="text-align:left;">-</td></tr></tbody></table><hr><h2 id="saberes-contenido-analitico" tabindex="-1">SABERES (Contenido Analítico) <a class="header-anchor" href="#saberes-contenido-analitico" aria-label="Permalink to &quot;SABERES (Contenido Analítico)&quot;">​</a></h2><p><strong>Unidad 1: Problema o situación que requiera desarrollo de aplicaciones informáticas</strong></p><ul><li>Levantamiento de Información.</li><li>Cuantificación de datos y análisis de necesidades.</li><li>Planificación y organización por áreas de saberes: Hardware y Software.</li></ul><p><strong>Unidad 2: Proceso de Administración de la calidad del Proyecto</strong></p><ul><li>Factores y métricas de calidad del Proyecto en función al área de saberes: hardware y software.</li></ul><p><strong>Unidad 3: Elaboración de la propuesta del Proyecto</strong></p><ul><li>Estimaciones de la propuesta (recurso, riesgo, tiempo, esfuerzo, impacto).</li><li>Estudio de factibilidad.</li><li>Propuesta y Presentación.</li></ul><p><strong>Unidad 4: Ejecución en gestión de proyectos</strong></p><ul><li>Aplicación de la metodología seleccionada según el área de saberes: hardware y software.</li></ul><p><strong>Unidad 5: Diseño</strong></p><ul><li>Diseño socio-tecnológico.</li></ul><p><strong>Unidad 6: Implantación</strong></p><ul><li>Estrategia de implantación del proyecto.</li><li>Ejecución y evaluación de la implantación.</li></ul><p><strong>Unidad 7: Evaluación, Pruebas y Optimización</strong></p><ul><li>Establecimiento de los indicadores de evaluación del proyecto.</li><li>Planificación y aplicación de las pruebas.</li><li>Detección y Corrección de errores.</li></ul><p><strong>Unidad 8: Manuales e informe final</strong></p><ul><li>Desarrollo de los manuales requeridos en el proyecto y entrenamiento a usuarios.</li><li>Evaluación del proyecto sociotecnológico.</li><li>Evaluación del informe final.</li></ul><hr><h2 id="estrategias" tabindex="-1">ESTRATEGIAS <a class="header-anchor" href="#estrategias" aria-label="Permalink to &quot;ESTRATEGIAS&quot;">​</a></h2><ul><li>Los actores deben abordar la comunidad para conocerla, describirla y detectar necesidades.</li><li>Realizar talleres, conversatorios o charlas con invitados especiales de organismos que apoyen la ejecución de proyectos.</li><li>Investigar sobre los proyectos informáticos locales, regionales y nacionales y los organismos que apoyan la ejecución de los mismos.</li><li>Plantear alternativas de soluciones ante situaciones y problemas reales, relacionados con soluciones informáticas.</li></ul><hr><h2 id="recursos" tabindex="-1">RECURSOS <a class="header-anchor" href="#recursos" aria-label="Permalink to &quot;RECURSOS&quot;">​</a></h2><ul><li>Pizarra magnética</li><li>Marcadores</li><li>Material Educativo Computarizado: Material Instructivo, Software</li><li>Computador</li><li>Proyector Multimedia</li><li>Plataforma Tecnológica</li><li>Aula de encuentros, aula taller, laboratorios.</li></ul><hr><h2 id="evaluacion" tabindex="-1">EVALUACIÓN <a class="header-anchor" href="#evaluacion" aria-label="Permalink to &quot;EVALUACIÓN&quot;">​</a></h2><p>Entrega y presentación del Informe: indicándose las actividades y fases desarrolladas. Coevaluación y Autoevaluación.</p><hr><h2 id="referencias" tabindex="-1">REFERENCIAS <a class="header-anchor" href="#referencias" aria-label="Permalink to &quot;REFERENCIAS&quot;">​</a></h2><ul><li>Villarroel, E. y Esté, P. (2008). Los Proyectos de Participación Comunitaria y su Práctica Social. Manual de Ejecución para Estudiantes Universitarios. Valencia – Venezuela.</li><li>Hernández, R., Fernández, C., Collado, P., Baptista, L. (2006). Metodología de la Investigación. 4ta Ed. Mc Graw Hill. México.</li><li>Crespo, M. (2009). Guía de diseño de proyectos sociales comunitarios bajo el enfoque del marco lógico. Conceptos esenciales y aplicaciones. Caracas – Venezuela.</li><li>Sarmiento, M. y Abreu, M. (2009). Cómo Diseñar Proyectos Comunitarios (Bajo el enfoque del Marco Lógico). Guía teórico-práctica. Ministerio del Poder Popular para Ciencia, Tecnología e Industrias Intermedias. Fundacite Zulia. Venezuela.</li><li>Ortegón, E., Pacheco, J. y Prieto, A. (2005). Metodología del Marco Lógico para la Planificación, el Seguimiento y la Evaluación de Proyectos y Programas. CEPAL. Serie Manuales. Chile.</li><li>Instituto Politécnico Nacional (2002). Metodología para el Análisis FODA. Dirección de Planeación y Organización. México.</li><li>Sommerville, L (2006). (8va. ed). Mexico: Pearson.</li><li>Pressman, R. (2002). Ingeniería de software. Un enfoque práctico. (5ª ed.). España: McGraw-Hill Interamericana de España, S.A.</li><li>McLeod, R. (2000). Sistemas de información gerencial. México:Editorial: Prentice Hall.</li><li>Ruble, D. (1998). Análisis y Diseño Práctico de Sistemas. México: Editorial: Prentice Hall.</li></ul>',33)])])}const m=a(t,[["render",r]]);export{g as __pageData,m as default};
